<div class="properties-page-header"><div><h1>Proprietários</h1><p><?= (int)$total ?> cadastro(s) encontrados</p></div><div class="properties-page-actions"><?php if (($currentUser['role'] ?? '') === 'admin'): ?><a href="/leads/import?dataset=owners&amp;return_to=owners" role="button" class="outline secondary">Importar CSV</a><?php endif; ?><a href="/owners/new" role="button">Cadastrar proprietário</a></div></div>
<form class="properties-filters" method="get" action="/owners"><label>Buscar proprietário ou imóvel<input type="search" name="q" value="<?= $e($q) ?>" placeholder="Nome, telefone, e-mail ou código"></label><button type="submit">Buscar</button><?php if($q!==''): ?><a href="/owners" role="button" class="outline secondary">Limpar</a><?php endif; ?></form>
<p class="properties-scroll-hint">Deslize horizontalmente para consultar todas as colunas.</p><div class="properties-table-wrap"><table class="properties-table"><thead><tr><th>Proprietário</th><th>Telefone</th><th>E-mail</th><th>Imóveis vinculados</th><th></th></tr></thead><tbody>
<?php foreach($owners as $owner): ?><tr><td><a href="/owners/<?= (int)$owner['id'] ?>"><strong><?= $e($owner['name']) ?></strong></a></td><td><?= $e($formatPhone($owner['phone'])) ?></td><td><?= $e($owner['email']?:'—') ?></td><td><?php if($owner['property_codes']): foreach(explode(',',$owner['property_codes']) as $code): ?><a href="/properties?q=<?= rawurlencode($code) ?>" class="owner-code"><?= $e($code) ?></a> <?php endforeach; else: ?>—<?php endif; ?><small>(<?= (int)$owner['property_count'] ?>)</small></td><td><a href="/owners/<?= (int)$owner['id'] ?>">Abrir</a></td></tr><?php endforeach; ?>
<?php if(!$owners): ?><tr><td colspan="5" class="properties-empty-state"><?= $q!==''?'Nenhum proprietário encontrado para esta busca.':'Ainda não há proprietários cadastrados. Cadastre o primeiro para relacionar seus imóveis.' ?></td></tr><?php endif; ?></tbody></table></div>
<?php if($pages>1): ?><nav class="properties-pagination" aria-label="Paginação"><ul><?php if($page>1): ?><li><a href="?q=<?= rawurlencode($q) ?>&page=<?= $page-1 ?>">Anterior</a></li><?php endif; ?><li>Página <?= $page ?> de <?= $pages ?></li><?php if($page<$pages): ?><li><a href="?q=<?= rawurlencode($q) ?>&page=<?= $page+1 ?>">Próxima</a></li><?php endif; ?></ul></nav><?php endif; ?>
